// Conta RD é compartilhada (Redacted, Redacted...): usar só o funil da REDACTED.
const p = $input.all().map(i => i.json).find(x => (x.name || '').toUpperCase().includes('REDACTED'));
if (!p) throw new Error('Funil REDACTED CONTABILIDADE não encontrado no RD.');
return [{ json: { pipelineId: p.id, nome: p.name, etapas: (p.deal_stages || []).map(s => s.id) } }];

// Sem IA: números do funil REDACTED no mês pedido (AAAA-MM; vazio = mês atual) + o que está aberto agora.
let mes = '';
try { mes = String($('Pedido do agente').first().json.mes || '').trim(); } catch (e) {}
const tz = 'America/Sao_Paulo';
const agora = new Date();
const mesAtual = agora.toLocaleDateString('en-CA', { timeZone: tz }).slice(0, 7);
if (!/^\d{4}-\d{2}$/.test(mes)) mes = mesAtual;
const hoje = agora.toLocaleDateString('en-CA', { timeZone: tz });
const dia = d => d ? new Date(d).toLocaleDateString('en-CA', { timeZone: tz }) : '';
const brl = v => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const valor = d => Number(d.amount_total || 0) || Number(d.amount_montly || 0) + Number(d.amount_unique || 0);
const etapas = new Set($('Funil REDACTED').first().json.etapas);
const r = $input.first().json;
const todas = (r.deals || []).filter(d => etapas.has(d.deal_stage && d.deal_stage.id));
const noMes = d => dia(d.closed_at).slice(0, 7) === mes;
const ganhas = todas.filter(d => d.win === true && noMes(d));
const perdidas = todas.filter(d => d.win === false && noMes(d));
const criadas = todas.filter(d => dia(d.created_at).slice(0, 7) === mes);
const abertas = todas.filter(d => d.win === null || d.win === undefined);
const porEtapa = {};
abertas.forEach(d => { const n = (d.deal_stage && d.deal_stage.name) || '?'; porEtapa[n] = (porEtapa[n] || 0) + 1; });
const porVendedor = {};
ganhas.forEach(d => { const n = (d.user && d.user.name) || '?'; porVendedor[n] = porVendedor[n] || { vendas: 0, valor: 0 }; porVendedor[n].vendas++; porVendedor[n].valor += valor(d); });
const motivos = {};
perdidas.forEach(d => { const m = (d.deal_lost_reason && d.deal_lost_reason.name) || 'sem motivo registrado'; motivos[m] = (motivos[m] || 0) + 1; });
const diasParado = d => d.updated_at ? Math.floor((agora - new Date(d.updated_at)) / 86400000) : null;
return [{ json: {
  funil: 'REDACTED CONTABILIDADE (RD CRM)',
  mes,
  aviso: r.has_more ? 'ATENÇÃO: o RD tem mais de 200 negociações neste funil; números podem estar incompletos.' : '',
  ganhas_no_mes: ganhas.length,
  valor_ganho_no_mes: brl(ganhas.reduce((s, d) => s + valor(d), 0)),
  ganhas_hoje: ganhas.filter(d => dia(d.closed_at) === hoje).map(d => d.name),
  perdidas_no_mes: perdidas.length,
  motivos_de_perda: motivos,
  negociacoes_criadas_no_mes: criadas.length,
  vendas_por_vendedor: Object.entries(porVendedor).map(([n, v]) => n + ': ' + v.vendas + ' venda(s), ' + brl(v.valor)),
  abertas_agora: abertas.length,
  abertas_por_etapa: porEtapa,
  abertas_sem_proxima_tarefa: abertas.filter(d => !d.next_task).map(d => ({ negociacao: d.name, etapa: d.deal_stage && d.deal_stage.name, responsavel: d.user && d.user.name, dias_sem_mexer: diasParado(d) })),
  ultimas_ganhas: ganhas.sort((a, b) => new Date(b.closed_at) - new Date(a.closed_at)).slice(0, 8).map(d => dia(d.closed_at).split('-').reverse().slice(0, 2).join('/') + ' — ' + d.name + ' — ' + brl(valor(d)) + ' — ' + ((d.user && d.user.name) || '?')),
  observacao: 'Leitura direta do RD, sem IA. O Comercial às vezes lança a venda pontual direto como ganha (sem passar pelo funil), então poucas negociações abertas é normal.'
} }];
